import { useState, useEffect } from "react";
import api from "../api";
import socket from "../socket";
import PaymentPage from "./PaymentPage";

export default function UserDashboard() {
  const [services, setServices] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [selectedService, setSelectedService] = useState(null);
  const [location, setLocation] = useState("");
  const [showPayment, setShowPayment] = useState(false);
  const [user, setUser] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const decoded = JSON.parse(atob(token.split(".")[1]));
        setUser(decoded);
      } catch (err) {
        console.error("Error decoding token:", err);
      }
    }
    loadServices();
    loadBookings();
    socket.on("booking-update", () => {
      loadBookings();
    });
    return () => {
      socket.off("booking-update");
    };
  }, []);

  const loadServices = async () => {
    try {
      const response = await api.get("/services");
      setServices(response.data);
    } catch (err) {
      console.error("Error loading services:", err);
    }
  };

  const loadBookings = async () => {
    try {
      const response = await api.get("/bookings/my-bookings");
      setBookings(response.data);
    } catch (err) {
      console.error("Error loading bookings:", err);
    }
  };

  const handleBooking = (service) => {
    setSelectedService(service);
    setShowPayment(true);
  };

  const handlePaymentSuccess = async () => {
    try {
      const bookingData = {
        userId: user?.id,
        serviceName: selectedService.name,
        location: location,
        status: "pending",
        paymentStatus: "paid"
      };
      const response = await api.post("/bookings/book", bookingData);
      if (response.data === "Booking Created") {
        alert("Booking created successfully!");
        setShowPayment(false);
        setSelectedService(null);
        setLocation("");
        loadBookings();
      }
    } catch (err) {
      console.error("Error creating booking:", err);
      alert("Failed to create booking");
    }
  };

  const cancelBooking = async (bookingId) => {
    try {
      await api.post(`/bookings/status/${bookingId}`, { status: "cancelled" });
      loadBookings();
    } catch (err) {
      console.error("Error cancelling booking:", err);
    }
  };

  const getServiceIcon = (serviceName) => {
    const icons = {
      'Plumber': '🔧',
      'Electrician': '⚡',
      'AC Repair': '❄️',
      'Carpenter': '🪵',
      'House Cleaning': '🧹',
      'Painting': '🎨',
      'Pest Control': '🐛',
      'Gardening': '🌱',
      'Appliance Repair': '🔌',
      'Moving & Packing': '📦'
    };
    return icons[serviceName] || '🔧';
  };

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div className="dashboard-logo">🚀 FastAid</div>
        <button className="logout-btn" onClick={() => {
          localStorage.removeItem("token");
          window.location.href = "/";
        }}>
          Logout
        </button>
      </header>

      <div className="dashboard-content">
        <h1 className="dashboard-title">Welcome, User! 👋</h1>
        <p className="dashboard-subtitle">Browse and book our professional services</p>

        <div className="card-grid">
          {services.map((service) => (
            <div key={service._id} className="service-card">
              <div className="service-icon">{getServiceIcon(service.name)}</div>
              <h3 className="card-title">{service.name}</h3>
              <p className="card-text">Category: {service.category}</p>
              <div className="card-rating">
                <span className="rating-star">⭐</span>
                <span className="rating-value">{service.rating}</span>
              </div>
              <button 
                onClick={() => handleBooking(service)}
                className="btn btn-primary"
                style={{ marginTop: '15px', width: '100%' }}
              >
                Book Now
              </button>
            </div>
          ))}
        </div>

        {showPayment && (
          <div className="payment-container fade-in">
            <h3>Booking: {selectedService?.name}</h3>
            <div className="form-group" style={{ marginTop: '20px' }}>
              <label className="form-label">Location</label>
              <input
                type="text"
                value={location}
                onChange={(e) => setLocation(e.target.value)}
                placeholder="Enter your location"
                className="form-input"
              />
            </div>
            <PaymentPage onSuccess={handlePaymentSuccess} />
          </div>
        )}

        <div className="table-container" style={{ marginTop: '40px' }}>
          <h2 style={{ padding: '20px', margin: 0 }}>My Bookings</h2>
          {bookings.length === 0 ? (
            <div className="empty-state">
              <div className="empty-state-icon">📋</div>
              <div className="empty-state-title">No bookings yet</div>
              <p>Book a service to get started!</p>
            </div>
          ) : (
            <table className="table">
              <thead>
                <tr>
                  <th>Service</th>
                  <th>Location</th>
                  <th>Status</th>
                  <th>Payment</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {bookings.map((booking) => (
                  <tr key={booking._id}>
                    <td>{booking.serviceName}</td>
                    <td>{booking.location}</td>
                    <td>
                      <span className={`status-badge status-${booking.status}`}>
                        {booking.status}
                      </span>
                    </td>
                    <td>
                      <span className={`status-badge status-${booking.paymentStatus}`}>
                        {booking.paymentStatus}
                      </span>
                    </td>
                    <td>
                      {booking.status === "pending" && (
                        <button 
                          onClick={() => cancelBooking(booking._id)}
                          className="btn btn-danger btn-small"
                        >
                          Cancel
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}
